var n=`0548-thareed`;var i=`world-0548`;var a=`AE`;var o=`western-asia`;var r=4;var s=90;var l={en:`Thareed`,ua:`Тарід`};var d={en:`A traditional dish from United Arab Emirates, centered on lamb, yellow onion, potato, carrot. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Об'єднані Арабські Емірати. Основні складники: ягнятина, жовта цибуля, картопля, морква. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`lamb`,680,`g`],[`yellow-onion`,180,`g`],[`unsalted-butter`,55,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 70 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 70 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:70,i:[[`potato`,400,`g`],[`carrot`,300,`g`],[`tomato`,380,`g`],[`water`,1e3,`ml`],[`ground-cumin`,5,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`pita-bread`,5,`pcs`]]}];var m={slug:n,id:i,country:`AE`,region:o,servings:4,minutes:90,title:l,text:d,steps:g};export{a as country,m as default,i as id,s as minutes,o as region,r as servings,n as slug,g as steps,d as text,l as title};